//! `rbs_app::popups` reads where Slint placed its in-window popups (ADR-0034 decision 4):
//! a popup at a known place, one Slint clamps into the window, one opened from a popup,
//! and none after they close. Fails if a Slint upgrade changes the internals it reads.

#![allow(clippy::expect_used)] // Tests fail by panicking.

use rbs_app::popups;
use rbs_ui::layout::Rect;
use slint::ComponentHandle;

#[allow(missing_docs, reason = "generated by the slint! macro")]
mod probe {
    slint::slint! {
        export component Probe inherits Window {
            width: 400px;
            height: 300px;
            callback open-plain();
            callback open-clamped();
            callback open-nested();
            callback open-wide();
            callback close-all();
            open-plain => { plain.show(); }
            open-clamped => { clamped.show(); }
            open-nested => { outer.show(); }
            open-wide => { wide.show(); }
            close-all => { plain.close(); clamped.close(); outer.close(); wide.close(); }
            anchor := Rectangle {
                x: 50px;
                y: 40px;
                width: 100px;
                height: 20px;
                plain := PopupWindow {
                    x: 10px;
                    y: 20px;
                    width: 120px;
                    VerticalLayout { Rectangle { height: 80px; } }
                }
                clamped := PopupWindow {
                    x: 300px;
                    y: 0px;
                    width: 200px;
                    height: 60px;
                }
            }
            // Its child is wider than the popup, so Slint centres it and draws it
            // past both edges (as `EntryMenu` did before its root got a width).
            wide := PopupWindow {
                x: 100px;
                y: 200px;
                width: 60px;
                height: 40px;
                Rectangle { width: 100px; height: 50px; }
            }
            outer := PopupWindow {
                x: 20px;
                y: 30px;
                width: 100px;
                height: 100px;
                init => { inner.show(); }
                inner := PopupWindow {
                    x: 10px;
                    y: 10px;
                    width: 40px;
                    height: 30px;
                }
            }
        }
    }
}
use probe::Probe;

fn r(x: f32, y: f32, w: f32, h: f32) -> Rect {
    Rect { x, y, w, h }
}

fn open(probe: &Probe) -> Vec<Rect> {
    let mut out = vec![r(1.0, 1.0, 1.0, 1.0)];
    popups::open_in(probe.window(), &mut out);
    out
}

#[test]
fn reads_where_slint_placed_each_popup() {
    i_slint_backend_testing::init_no_event_loop();
    let probe = Probe::new().expect("the probe window");
    probe.show().expect("show");
    assert_eq!(open(&probe), vec![]);

    // Relative to its parent; the height from its layout.
    probe.invoke_open_plain();
    assert_eq!(open(&probe), vec![r(60.0, 60.0, 120.0, 80.0)]);

    // 50 + 300 + 200 > 400: Slint moves it left to fit the window. Opening it closes
    // its sibling (same parent).
    probe.invoke_open_clamped();
    assert_eq!(open(&probe), vec![r(200.0, 40.0, 200.0, 60.0)]);

    probe.invoke_close_all();
    assert_eq!(open(&probe), vec![]);

    // A popup opened from a popup: both, in window coordinates.
    probe.invoke_open_nested();
    assert_eq!(
        open(&probe),
        vec![r(20.0, 30.0, 100.0, 100.0), r(30.0, 40.0, 40.0, 30.0)]
    );
    probe.invoke_close_all();
    assert_eq!(open(&probe), vec![]);

    // Joined with what it draws: x 100 - 20, y 200 - 5, 100 by 50.
    probe.invoke_open_wide();
    assert_eq!(open(&probe), vec![r(80.0, 195.0, 100.0, 50.0)]);
    probe.invoke_close_all();
    assert_eq!(open(&probe), vec![]);
}
